def convert_passports(apps, _schema_editor):
    """Fill missing catalog metadata on every existing passport row.

    Identity, credentials, signing material, names and placement bindings are
    never rewritten: only empty catalog fields are filled, so a second run makes
    no change. Placements that cannot be read are skipped and reported, and rows
    that stay incomplete are logged by passport id with the fields they still
    need, instead of failing deployment.
    """
    ReusableLtiConfiguration = apps.get_model("lti_consumer", "ReusableLtiConfiguration")
    LtiConfiguration = apps.get_model("lti_consumer", "LtiConfiguration")

    unreadable = []
    incomplete = []
    for configuration in ReusableLtiConfiguration.objects.order_by('pk'):
        changes = {}

        if not configuration.normalized_name and configuration.name:
            changes['normalized_name'] = configuration.name.strip().casefold()

        placements = list(
            LtiConfiguration.objects.filter(lti_1p3_passport_id=configuration.pk).order_by('pk')
        )

        if not configuration.context_type:
            context = _stored_context(configuration.context_key) or _placement_context(placements)
            if context:
                changes['context_type'], changes['context_key'] = context

        bundle, skipped = _seed_bundle(placements)
        unreadable.extend(skipped)
        for field, value in bundle.items():
            if _should_fill(getattr(configuration, field), configuration._meta.get_field(field), value):
                changes[field] = value

        if not configuration.lti_1p3_tool_key_mode:
            inferred_mode = _inferred_tool_key_mode(configuration)
            if inferred_mode:
                changes['lti_1p3_tool_key_mode'] = inferred_mode

        for field, value in changes.items():
            setattr(configuration, field, value)
        if configuration.version == 'lti_1p3' and not configuration.lti_1p3_deployment_id:
            # Legacy launches always claimed deployment "1"; keep that effective value
            # instead of leaving a converted 1.3 configuration permanently incomplete.
            configuration.lti_1p3_deployment_id = '1'
            changes['lti_1p3_deployment_id'] = '1'
        if changes:
            configuration.save(update_fields=list(changes))

        missing = _missing_fields(configuration)
        if missing:
            incomplete.append(f'{configuration.passport_id} (missing: {", ".join(missing)})')

    if unreadable:
        log.warning("Reusable configuration conversion skipped unreadable placements: %s", unreadable)
    if incomplete:
        log.warning("Reusable configuration conversion left incomplete configurations: %s", incomplete)


